['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
  FILE *input_file, *output_file;
  char buffer[1024]; // Adjust buffer size as needed
  long bytesRead;
  unsigned int checksum = 0;

  // Open input file for reading
  input_file = fopen("input.txt", "r"); 
  if (input_file == NULL) {
    perror("Error opening input file");
    return 1;
  }

  // Read contents into buffer
  bytesRead = fread(buffer, 1, sizeof(buffer), input_file); 

  // Calculate checksum
  for (int i = 0; i < bytesRead; i++) {
    checksum += buffer[i];
  }

  // Open output file for writing
  output_file = fopen("output.txt", "w");
  if (output_file == NULL) {
    perror("Error opening output file");
    fclose(input_file);
    return 1;
  }

  // Write checksum and bytes read to output file
  fprintf(output_file, "Bytes Read: %ld\nChecksum: %u\n", bytesRead, checksum);

  // Close files
  fclose(input_file);
  fclose(output_file);

  if (checksum == 0) {
    printf("The input file is empty.\n");
  } else {
    printf("Checksum calculated successfully.\n");
  }

  return 0;
}
```

**Explanation:**

1. **Include headers:** Necessary for file operations, standard input/output, and string manipulation.
2. **Declare variables:**
   - `input_file` and `output_file`: FILE pointers to handle input and output files.
   - `buffer`: A character array to store the file contents (adjust size as needed).
   - `bytesRead`: Stores the number of bytes read from the input file.
   - `checksum`: An unsigned integer to accumulate the checksum value.
3. **Open input file:**
   - Uses `fopen()` to open "input.txt" in read mode ("r").
   - Checks for errors and handles them with `perror()`.
4. **Read file contents:**
   - Uses `fread()` to read data from the input file into the `buffer` array. 
5. **Calculate checksum:**
   - Iterates through each byte in the `buffer` and adds it to the `checksum` variable.
6. **Open output file:**
   - Uses `fopen()` to open "output.txt" in write mode ("w").
7. **Write to output file:**
   - Uses `fprintf()` to write the number of bytes read (`bytesRead`) and the calculated checksum (`checksum`) to the output file.
8. **Close files:**
   - Calls `fclose()` to close both input and output files.
9. **Handle empty file:**
   - Checks if the `checksum` is 0, indicating an empty input file.
10. **Print messages:**
    - Prints messages indicating success or if the input file was empty.



**To use this code:**

