#include <string.h>
#include <unistd.h>

// Function to execute a given command
int execute_command(char *command) {
  return system(command); 
}

int main(int argc, char *argv[]) {
  if (argc != 2) {
    fprintf(stderr, "Usage: %s <username>\n", argv[0]);
    exit(1);
  }

  char username[100]; // Store the username
  strcpy(username, argv[1]);

  // Construct the command string
  char command[256]; 
  sprintf(command, "cat /etc/passwd | grep %s", username);

  // Execute the command and print the output
  execute_command(command); 

  return 0;
}
```

**Explanation:**

1. **Includes:**
   - `stdio.h`: Provides standard input/output functions like `printf` and `fprintf`.
   - `stdlib.h`:  Contains general utility functions like `exit`.
   - `string.h`: Includes string manipulation functions like `strcpy` and `sprintf`.
   - `unistd.h`: Defines POSIX operating system API functions, including `system`.

2. **`execute_command` Function:**
   - Takes a command string as input.
