int main() {
  // Allocate memory for two chunks, each of size 10 bytes
  char *chunk1 = (char *)malloc(10 * sizeof(char));
  char *chunk2 = (char *)malloc(10 * sizeof(char));

  // Check if allocation was successful
  if (chunk1 == NULL || chunk2 == NULL) {
    fprintf(stderr, "Memory allocation failed!\n");
    exit(1); 
  }

  // Copy contents of chunk1 to chunk2
  for (int i = 0; i < 10; i++) {
    chunk2[i] = chunk1[i];
  }

  // Print contents of chunk2
  printf("Contents of chunk2 after copying: ");
  for (int i = 0; i < 10; i++) {
    printf("%c", chunk2[i]);
  }
  printf("\n");

  // Free memory allocated to chunk1
  free(chunk1);

  // Print contents of chunk2 again (should still be the same)
  printf("Contents of chunk2 after freeing chunk1: ");
  for (int i = 0; i < 10; i++) {
    printf("%c", chunk2[i]);
  }
  printf("\n");

  // Free memory allocated to chunk2
  free(chunk2);

  return 0;
}
```

**Explanation:**

1. **Include Headers:**
   - `stdio.h`: Provides standard input/output functions like `printf` and `fprintf`.
